module solve_linear_congruence (\n    input clk,\n    input rst_n,\n    input start,\n    input signed [31:0] a,\n    input signed [31:0] b,\n    input [31:0] P,\n    input [31:0] M,\n    output reg [31:0] x,\n    output reg done\n);\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] FINISH = 2'd2;\n    reg [1:0] state;\n    reg [31:0] x_reg;\n    reg [31:0] cycle_counter;\n\n    wire signed [63:0] product = a * x_reg;\n    wire signed [63:0] sum = product + b;\n    wire signed [63:0] mod_value = sum % $signed(M);\n    wire signed [31:0] adjusted_mod = (mod_value < 0) ? mod_value + $signed(M) : mod_value[31:0];\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            x <= 32'd0;\n            x_reg <= 32'd0;\n            done <= 1'b0;\n            cycle_counter <= 32'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_counter <= 32'd0;\n                    if (start) begin\n                        state <= COMPUTE;\n                        x_reg <= 32'd0;\n                    end\n                end\n                \n                COMPUTE: begin\n                    cycle_counter <= cycle_counter + 32'd1;\n                    if (adjusted_mod == P) begin\n                        x <= x_reg;\n                        state <= FINISH;\n                    end else if (x_reg == M - 32'd1 || cycle_counter >= 32'd100_000) begin\n                        state <= FINISH;\n                    end else begin\n                        x_reg <= x_reg + 32'd1;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule